package models

import "gorm.io/gorm"

// Migrate is what DATABASE_SYNC=true runs. `apso generate` (an @apso/cli
// release from November 2026 or later) overwrites this file with one that builds the exact schema
// `apso migrate` builds. This fallback keeps projects generated by older CLIs
// compiling and behaving as before: gorm AutoMigrate over every model.
func Migrate(db *gorm.DB) error {
	return db.AutoMigrate(All()...)
}
